class Solution {
public:
    int largestSumAfterKNegations(vector<int>& nums, int k) {
        int count[201] = {0};
        for (int x : nums) count[x + 100]++;

        for (int v = -100; v <= -1 && k > 0; v++) {
            int idx = v + 100;
            if (count[idx] > 0) {
                int flip = count[idx] < k ? count[idx] : k;
                count[idx] -= flip;
                count[-v + 100] += flip;
                k -= flip;
            }
        }

        if (k % 2 == 1) {
            if (count[100] == 0) {
                for (int v = 1; v <= 100; v++) {
                    if (count[v + 100] > 0) {
                        count[v + 100]--;
                        count[-v + 100]++;
                        break;
                    }
                }
            }
        }

        int sum = 0;
        for (int v = -100; v <= 100; v++) {
            sum += v * count[v + 100];
        }
        return sum;
    }
};
